<script setup>
import {computed,shallowRef} from 'vue'
import {useRoute} from 'vue-router'
import {products,path,fmt} from '../data'
import {session,openModal} from '../session'
import Coin from '../components/Coin.vue'
import Icon from '../components/Icon.vue'
const route=useRoute(),filter=shallowRef("aiQuant.templates.filterAll"),sort=shallowRef(false)
const section=computed(()=>route.params.section||'simple'),product=computed(()=>section.value==='simple'&&route.params.id?products.find(p=>p.id===route.params.id):null)
const visible=computed(()=>products.filter(p=>filter.value==="aiQuant.templates.filterAll"||p.type===filter.value).toSorted((a,b)=>sort.value?a.rate-b.rate:b.rate-a.rate))
const featured=[products[1],products[4],products[7]]
function subscribe(p){openModal('subscribe',"aiQuant.quantFund.detail.flowStep1Title",{...p,max:500000})}
</script>
