<dl class="details-list"><dt>{{ $t("aiQuant.quantFund.card.availableQuota") }}</dt><dd>{{ $t(product.remaining) }} {{ $t(product.symbol) }}</dd><dt>{{ $t("earn.productDetail.keyFacts.totalSubscribed") }}</dt><dd>{{ $t(fmt(product.min)) }} {{ $t(product.symbol) }}</dd></dl></div></div><div class="card"><h2>{{ $t("earn.productDetail.risk.title") }}</h2><p class="muted" style="line-height:1.8;margin-top:16px">{{ $t("earn.productDetail.risk.notGuaranteed") }}<br/>{{ $t("earn.productDetail.risk.earlyRedemption") }}<br/>{{ $t("finance.ui.localPreviewOnlyNoRealSubscription") }}</p></div><div class="sticky-action"><div><b class="green-link">{{ $t(product.rate.toFixed(4)) }}%</b><small class="muted">{{ $t("finance.ui.dailyRate") }}{{ $t(product.days||"aiQuant.quantFund.card.termFlexible") }}{{ $t("finance.ui.minimum") }}{{ $t(fmt(product.min)) }} {{ $t(product.symbol) }}</small></div><button class="primary-button" @click="subscribe(product)">{{ $t("aiQuant.quantFund.detail.flowStep1Title") }}</button></div></div>
