;aiQuant.templates.filterAll&quot;,&quot;aiQuant.quantFund.card.termFlexible&quot;,&quot;aiQuant.landing.quantFund.chipA&quot;]" :key="f" :class="{active:filter===f}" :aria-pressed="filter===f" @click="filter=f">{{ $t(f) }}</button><button @click="sort=!sort">{{ $t("earn.table.columns.dailyRate") }}{{ $t(sort?'↑':'↓') }}</button></div><div class="finance-table card"><table><thead><tr><th>{{ $t("earn.table.columns.product") }}</th><th>{{ $t("assets.fundRecordsType") }}</th><th>{{ $t("earn.table.columns.term") }}</th><th>{{ $t("earn.table.columns.minAmount") }}</th><th>{{ $t("aiQuant.quantFund.card.availableQuota") }}</th><th>{{ $t("earn.table.columns.dailyRate") }}</th><th>{{ $t("aiQuant.table.columns.action") }}</th></tr></thead><tbody><tr v-for="p in visible" :key="p.id"><td><RouterLink :to="path('/earn/simple/'+p.id)" class="coin-label"><Coin :symbol="p.symbol"/><span>{{ $t(p.name) }}<small class="muted" style="display:block">{{ $t(p.symbol) }}</small></span></RouterLink></td><td :data-label="$t('assets.fundRecordsType')">{{ $t(p.type) }}</td><td :data-label="$t('earn.table.columns.term')">{{ (p.days ? $t('common.durationDays', {count: p.days}) : $t('aiQuant.quantFund.card.termFlexible')) }}</td><td :data-label="$t('earn.table.columns.minAmount')">{{ $t(fmt(p.min)) }} {{ $t(p.symbol) }}</td><td :data-label="$t('aiQuant.quantFund.card.availableQuota')">{{ $t(p.remaining) }} {{ $t(p.symbol) }}</td><td :data-label="$t('earn.table.columns.dailyRate')" class="green-link">{{ $t(p.rate.toFixed(4)) }}%</td><td><RouterLink :to="path('/earn/simple/'+p.id)" class="pill primary">{{ $t("aiQuant.quantFund.detail.flowStep1Title") }}</RouterLink></td></tr></tbody></table></div><p class="mini-label section-gap">{{ $t("finance.ui.reviewEachProductSTermsAndRedemptionRulesDisplayed") }}</p></template>
